import{_ as d,o as a,c as r,a4 as l}from"./chunks/framework.CeDiN6Rk.js";const c=JSON.parse('{"title":"Anno 117 DLC03「デルタの夜明け」攻略・新要素まとめ","description":"Anno 117 DLC03「デルタの夜明け（Dawn of the Delta）」の情報ページ。エジプト地方アイギュプト・灌漑システム・新祭神セベクなどを解説（2026年11月5日リリース）。","frontmatter":{"title":"Anno 117 DLC03「デルタの夜明け」攻略・新要素まとめ","description":"Anno 117 DLC03「デルタの夜明け（Dawn of the Delta）」の情報ページ。エジプト地方アイギュプト・灌漑システム・新祭神セベクなどを解説（2026年11月5日リリース）。"},"headers":[],"relativePath":"guide/dlc03-dawn-of-delta.md","filePath":"guide/dlc03-dawn-of-delta.md"}'),i={name:"guide/dlc03-dawn-of-delta.md"};function e(o,t,h,n,s,u){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="dlc03・デルタの夜明け" tabindex="-1">DLC03・デルタの夜明け <a class="header-anchor" href="#dlc03・デルタの夜明け" aria-label="Permalink to &quot;DLC03・デルタの夜明け&quot;">​</a></h1><blockquote><p>本ページの内容は今後変更される可能性があります。</p></blockquote><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><ul><li>舞台は帝国南東部の<strong>アイギュプト</strong>（ナイル川デルタ地方）。</li><li>新規ゲーム開始時の地域として選択できるほか、既存セーブでもDLC有効化により探索可能になります。</li><li><strong>灌漑システム</strong>・新祭神・独自の軍事ユニットが導入されました。</li><li><strong>2026年11月5日</strong>、無料アップデート3.0と同時にリリースされました。</li></ul><h2 id="地形・建築エリア" tabindex="-1">地形・建築エリア <a class="header-anchor" href="#地形・建築エリア" aria-label="Permalink to &quot;地形・建築エリア&quot;">​</a></h2><p>土地は3つのゾーンに分かれます。</p><table tabindex="0"><thead><tr><th>ゾーン</th><th>特徴</th></tr></thead><tbody><tr><td>砂漠エリア</td><td>内陸にあり、作物は作れないが、建物は建てられる。都市の建設に適している</td></tr><tr><td>農地</td><td>海岸沿いにあり、農業と港の建設に使う</td></tr><tr><td>氾濫原</td><td>川沿いにあり、洪水の影響を受ける。泥のおかげで建物の生産量が増える。葦・泥などの産地</td></tr></tbody></table><p>「農地」と「氾濫原」は、農場の建設画面に出る「地形のタイプ」の表記です。オーツ麦農場のように、農地と氾濫原のどちらにも建てられる農場があります。氾濫原に建てると、「1tをサイクル毎に追加で生産」の効果が付きます。「砂漠エリア」はゲーム内の表記ではなく、このWikiでの呼び名です（日本語版の正式な表記は未確認です）。作物は作れず、建物は建てられます。</p><h2 id="住民層" tabindex="-1">住民層 <a class="header-anchor" href="#住民層" aria-label="Permalink to &quot;住民層&quot;">​</a></h2><p>初期層は<strong>麦打ち人</strong>（農業の伝統を担う階層）です。基本の需要を満たすと、次の2路線から選びます。</p><table tabindex="0"><thead><tr><th>路線</th><th>第2階層</th><th>第3階層</th></tr></thead><tbody><tr><td>クマト（伝統）</td><td>陶工</td><td>奉唱巫女</td></tr><tr><td>ギリシャ・ローマ</td><td>書記</td><td>ギムナシアリコス</td></tr></tbody></table><p>各層の需要は<a href="/wiki/population.html#アイギュプト住民層">住民層のページ</a>にまとめています。</p><h2 id="公共施設" tabindex="-1">公共施設 <a class="header-anchor" href="#公共施設" aria-label="Permalink to &quot;公共施設&quot;">​</a></h2><ul><li><strong>クマト路線</strong>: 薬局（薬草園つき。健康と知識）、聖域または神殿（現地の神々）、岩窟墓（上流階級向け。山のスロットが必要）、天文台（信仰+5、知識+3）。</li><li><strong>ローマ路線</strong>: 劇場、浴場（水道橋が必要）、図書館（オイルランプに注意）。</li></ul><h2 id="新しい商品・生産チェーン" tabindex="-1">新しい商品・生産チェーン <a class="header-anchor" href="#新しい商品・生産チェーン" aria-label="Permalink to &quot;新しい商品・生産チェーン&quot;">​</a></h2><ul><li><strong>魔除けのお守り</strong>（陶工向け）: 銅と砂から青い染料を作り、現地の粘土で作った魔除けのお守りを染めます。</li><li><strong>書記道具一式</strong>（書記向け）: パピルス（葦が必要）と、現地の鉱物から作る顔料で作ります。</li><li><strong>シストラム</strong>（奉唱巫女向け）: 現地の銅と錫から作った青銅に、氾濫原で採れるビーズを組み合わせます。</li><li>パン・ビール・石鹸などは、ラティウム・アルビオン・アイギュプトのどこで作るか、輸入か現地生産かを選べます。</li><li>需要品の一覧は<a href="/wiki/population.html#アイギュプト住民層">住民層のページ</a>を参照。</li><li><strong>ラティウム・アルビオンの住民も、アイギュプトの商品を欲しがります</strong>。アップデート3.0で、下の表の需要品が加わりました。ラティウムの島の需要を満たすには、アイギュプトからの輸入が必要です。詳しくは<a href="/wiki/population.html#エクィテス">住民層のページ</a>を参照。</li></ul><table tabindex="0"><thead><tr><th>地域</th><th>住民層</th><th>加わった需要品</th></tr></thead><tbody><tr><td>ラティウム</td><td>エクィテス</td><td>ナツメヤシ、コール、書記道具一式</td></tr><tr><td>ラティウム</td><td>パトリキ</td><td>ナツメヤシ、コール、書記道具一式、カフク、ポッパエアのミルク、象牙の小箱、シストラム</td></tr><tr><td>アルビオン</td><td>スミス</td><td>コール、魔除けのお守り</td></tr><tr><td>アルビオン</td><td>アルダー</td><td>コール、魔除けのお守り、青スイレン茶</td></tr><tr><td>アルビオン</td><td>メルカトル</td><td>書記道具一式</td></tr><tr><td>アルビオン</td><td>ノビレス</td><td>書記道具一式、希少な肉の盛り合わせ、香油</td></tr></tbody></table><h2 id="アイギュプトの生産施設" tabindex="-1">アイギュプトの生産施設 <a class="header-anchor" href="#アイギュプトの生産施設" aria-label="Permalink to &quot;アイギュプトの生産施設&quot;">​</a></h2><p>アイギュプトで新しく作れる商品の生産施設です。サイクルは1サイクルの秒数で、労働力はその施設に必要な住民層と人数です。維持費の単位はコインです。</p><div class="stack-table"><table tabindex="0"><thead><tr><th>施設</th><th>サイクル（秒）</th><th>労働力</th><th>維持費</th><th>材料</th><th>製品</th></tr></thead><tbody><tr><td>青色顔料工房</td><td>90</td><td>陶工8</td><td>20</td><td>銅鉱石、シリカ</td><td>アイギュプトの青</td></tr><tr><td>ゴマ圧搾所</td><td>90</td><td>陶工8</td><td>16</td><td>ゴマのさや</td><td>ゴマ油</td></tr><tr><td>詰め物肉工房</td><td>120</td><td>陶工6</td><td>14</td><td>雁、小麦</td><td>詰め物入りガチョウ</td></tr><tr><td>カイク工房</td><td>90</td><td>奉唱巫女12</td><td>22</td><td>蜂の巣、小麦粉</td><td>カフク</td></tr><tr><td>煎じ茶工房</td><td>90</td><td>奉唱巫女12</td><td>22</td><td>青スイレン、蜂の巣</td><td>青スイレン茶</td></tr><tr><td>ビーズ工房</td><td>90</td><td>麦打ち人4</td><td>8</td><td>ビーズ</td><td>ウェセクの首輪</td></tr><tr><td>プリーツ工房</td><td>90</td><td>陶工6</td><td>10</td><td>布</td><td>シェンティ</td></tr><tr><td>コリュラ工房</td><td>90</td><td>陶工6</td><td>10</td><td>獣脂、石炭</td><td>コール</td></tr><tr><td>裁縫工房</td><td>90</td><td>奉唱巫女10</td><td>24</td><td>布、アイギュプトの青</td><td>カラシリス</td></tr><tr><td>香油工房</td><td>90</td><td>奉唱巫女8</td><td>14</td><td>青スイレン、ゴマ油</td><td>香油</td></tr><tr><td>ガラス細工工房</td><td>90</td><td>陶工6</td><td>12</td><td>泥、アイギュプトの青</td><td>魔除けのお守り</td></tr><tr><td>ランプ工房</td><td>90</td><td>陶工8</td><td>14</td><td>泥、ゴマ油</td><td>オイルランプ</td></tr><tr><td>ティンパニ工房</td><td>120</td><td>奉唱巫女12</td><td>24</td><td>ビーズ、青銅</td><td>シストラム</td></tr><tr><td>泥レンガ集積場</td><td>30</td><td>麦打ち人2</td><td>8</td><td>泥、葦</td><td>泥レンガ</td></tr><tr><td>石灰岩の石工所</td><td>60</td><td>陶工5</td><td>10</td><td>石灰岩</td><td>石灰岩レンガ</td></tr><tr><td>メリクラトール</td><td>90</td><td>ギムナシアリコス8</td><td>12</td><td>蜂の巣、サンガ牛</td><td>蜂蜜入りミルク</td></tr><tr><td>パピルス職人</td><td>120</td><td>書記6</td><td>12</td><td>葦</td><td>パピルス</td></tr><tr><td>大地の美食家</td><td>120</td><td>ギムナシアリコス8</td><td>16</td><td>カバ、ザクロ</td><td>希少な肉の盛り合わせ</td></tr><tr><td>美容師</td><td>120</td><td>ギムナシアリコス8</td><td>16</td><td>ザクロ、蜂蜜入りミルク</td><td>ポッパエアのミルク</td></tr><tr><td>写本室</td><td>120</td><td>書記4</td><td>14</td><td>顔料、パピルス</td><td>書記道具一式</td></tr><tr><td>錠前師</td><td>90</td><td>ギムナシアリコス12</td><td>30</td><td>金、カバ</td><td>象牙の小箱</td></tr><tr><td>ナツメヤシ農場</td><td>60</td><td>麦打ち人4</td><td>6</td><td>—</td><td>ナツメヤシ</td></tr><tr><td>ラクダ牧場</td><td>120</td><td>陶工6</td><td>12</td><td>—</td><td>ラクダ</td></tr><tr><td>青スイレン農園</td><td>120</td><td>奉唱巫女8</td><td>4</td><td>—</td><td>青スイレン</td></tr><tr><td>ザクロ農場</td><td>90</td><td>麦打ち人4</td><td>8</td><td>—</td><td>ザクロ</td></tr><tr><td>サンガ牛牧場</td><td>60</td><td>麦打ち人4</td><td>8</td><td>—</td><td>サンガ牛</td></tr><tr><td>ビーズ工房</td><td>90</td><td>麦打ち人4</td><td>4</td><td>—</td><td>ビーズ</td></tr><tr><td>雁狩り小屋</td><td>60</td><td>麦打ち人6</td><td>6</td><td>—</td><td>雁</td></tr><tr><td>大型獣の狩猟小屋</td><td>60</td><td>ギムナシアリコス6</td><td>12</td><td>—</td><td>カバ</td></tr><tr><td>ゴマ農場</td><td>120</td><td>麦打ち人4</td><td>4</td><td>—</td><td>ゴマのさや</td></tr></tbody></table></div><ul><li>「ビーズ工房」は2種類あります。ビーズを作る施設と、ビーズからウェセクの首輪を作る施設です。</li><li>労働力の表記は「住民層＋人数」です。たとえば「陶工8」は、陶工の労働力が8必要という意味です。</li></ul><h2 id="穀倉" tabindex="-1">穀倉 <a class="header-anchor" href="#穀倉" aria-label="Permalink to &quot;穀倉&quot;">​</a></h2><ul><li>範囲内の農場の生産性が+15%、人口ボーナスが+1。農産物を1基あたり100t追加で保管できます。</li><li>スキルでアップグレードできます。穀物庫は、スキルで大型穀物庫、広大な穀物庫にアップグレードでき、保管量は100t、200t、300tと、アップグレードのたびに100t増えます。積込用スロープも2つ増えます。</li><li>維持費と必要な労働力（麦打ち人）は、穀物庫が3と2、大型穀物庫が5と4、広大な穀物庫が8と6です。</li><li>保管上限を超えるとあふれ、ネズミが出ることがあります。超過が多く、穀倉のレベルが低いほど起きやすく、島の健康度が下がって総督の決定を誘発します。</li><li>対策は、穀倉のアップグレードと、ネズミ対策の専門家の雇用です。 <ul><li><strong>猫の友キャットゥルス</strong>（レア）: ネズミの危険性が60%下がります。多数の交易商や祭りから、低確率でランダムに手に入ります。</li><li><strong>猫使い</strong>（コモン）: ネズミの危険性が20%下がります。ヘロン地方長官やウァレリアなどとの取引で手に入ります。</li><li><strong>ミウト、水鳥の脅威</strong>（レジェンダリー、財政）: 総督のヴィラに付けると、信仰の範囲効果が+2になり、ネズミの危険性も抑えます。ネズミの危険性は80%下がるとデータにあり、入手先はクエスト「パンドラのアンフォラ」です（この2点は実機では未確認です）。</li></ul></li></ul><h2 id="洪水と灌漑" tabindex="-1">洪水と灌漑 <a class="header-anchor" href="#洪水と灌漑" aria-label="Permalink to &quot;洪水と灌漑&quot;">​</a></h2><h3 id="季節の影響" tabindex="-1">季節の影響 <a class="header-anchor" href="#季節の影響" aria-label="Permalink to &quot;季節の影響&quot;">​</a></h3><ul><li><strong>氾濫期</strong>: 氾濫原の建物の生産性が75%下がります。州全体で、全建物の健康が-2、防火が+2になります。</li><li><strong>収穫期</strong>: 氾濫原の生産建物の生産量が、サイクルごとに+1tになります。</li></ul><h3 id="灌漑の方式" tabindex="-1">灌漑の方式 <a class="header-anchor" href="#灌漑の方式" aria-label="Permalink to &quot;灌漑の方式&quot;">​</a></h3><ul><li><strong>貯水池方式</strong>: 海岸に貯水池を建て、内陸へ運河を伸ばします。運河の両側8フィールドが農地になり、乾燥地帯を農業用地に変えられます。その分、都市の建設スペースは減ります。農業専用の島を作る手もあります。</li><li><strong>水路の水溜め</strong>: 運河に接続し、道路もつなぐと、範囲内で健康+1、防火+3になります。</li><li><strong>ノリア方式</strong>（第3階層で解放）: 川の水をノーリア水車でくみ上げ、水道橋で内陸へ送ります。貯水槽（シスターン）は浴場の水源になるほか、周囲の円形範囲も農地にします。</li></ul><h2 id="スキルツリー" tabindex="-1">スキルツリー <a class="header-anchor" href="#スキルツリー" aria-label="Permalink to &quot;スキルツリー&quot;">​</a></h2><p>アイギュプトには、専用のスキルツリーが用意されています。スキルで次のことができるようになります。</p><ul><li>氾濫原でより多様な作物を育て、生産ボーナスを得る。</li><li>灌漑設備を強化して、生産建物の水使用量を減らす。長い運河も建設できるようになる。</li><li>アイギュプトで石鹸などを生産できるようにする。</li><li>現地の新しい神々を発見する。</li></ul><p>スキルごとの効果の一覧は、<a href="/wiki/techs-dlc03.html">スキルツリー・デルタの夜明け</a>にまとめています。</p><h2 id="宗教" tabindex="-1">宗教 <a class="header-anchor" href="#宗教" aria-label="Permalink to &quot;宗教&quot;">​</a></h2><p>新祭神が3柱導入されました。名前はゲームのアップデート3.0のゲーム内データの表記です。</p><ul><li><strong>セベク</strong>：「デルタ川の神」。研究なしで使えます。チーズソーセージ・詰めガチョウ・サンガ牛などの食料生産が増え、灌漑用水とボーナス人口も増えます。世界的な信仰ボーナスで鳩小屋が解放され、農園に付けると生産性が上がります。鳩小屋は農園に取り付けるモジュールで、サイロと同じ仕組みです。小麦を消費して動き、生産性と処理時間があります。なお、ゲーム内ヘルプによると、サイロが機能するには範囲内に倉庫が必要です。</li><li><strong>イシス・バステト</strong>：研究ツリーで発見が必要です。ラベンダー・香水・ナツメヤシの生産が増え、住民の商品消費量は減ります。世界の信仰が4,000になると、特大の祭壇「レプリカのスフィンクスの祭壇」が解放されます（範囲効果は人々+1・収入+1・名声+2、維持費26）。世界の信仰がさらに高いと、祭りの期間が延びます。</li><li><strong>トト・トリスメギストス</strong>：研究ツリーで発見が必要です。ガラス・ワイン・書字板・書記道具一式などの生産が増えます。島の収入と名声は知識レベルに連動します。世界の信仰が高まると、崇拝の効果「トトの書」で、図書館の範囲内の全建物の生産が20%増えます。</li></ul><p>エジプトの神を信仰すると、聖域・神殿の外観がエジプト風（猫やワニの聖域など）になります。</p><h3 id="_3柱で生産が増える建物" tabindex="-1">3柱で生産が増える建物 <a class="header-anchor" href="#_3柱で生産が増える建物" aria-label="Permalink to &quot;3柱で生産が増える建物&quot;">​</a></h3><p>島の祭神にすると、その島で次の建物の生産が増えます。増え方は信仰値に応じて段階的に上がります。建物名はゲームのアップデート3.0のゲーム内データの表記で、実機での確認はまだです。</p><table tabindex="0"><thead><tr><th>祭神</th><th>生産が増える建物</th></tr></thead><tbody><tr><td>セベク</td><td>小麦農場、大麦農場、アッケシソウ摘み、ザクロ農場、ハーブ園、養豚場、オーロックス牧場、サンガ牛牧場、雁狩り小屋、大型獣の狩猟小屋、乳工房、麦芽製造所、醸造所、ソーセージ職人、詰め物肉工房、大地の美食家、地窯</td></tr><tr><td>イシス・バステト</td><td>小麦農場、ゴマ農場、ラベンダー農家、青スイレン農園、ナツメヤシ農場、養蜂場、粉ひき所、ロバの製粉所、パン屋、ゴマ圧搾所、カイク工房、煎じ茶工房、香油工房</td></tr><tr><td>トト・トリスメギストス</td><td>ブドウ園、ワイン醸造業者、養蜂場、葦採集者、パピルス職人、写本室、鉱物の採石場、鉱物粉砕所、砂精製所、ガラス工房、ガラス吹き工、蝋版職人、銀鉱山、銀工房、ブローチ職人、サンダラック苗木場</td></tr></tbody></table><h2 id="ピラミッド" tabindex="-1">ピラミッド <a class="header-anchor" href="#ピラミッド" aria-label="Permalink to &quot;ピラミッド&quot;">​</a></h2><p>島ではなく、州全体のプロジェクトです。ナウクラティスの近くにあり、修復すると州全体にボーナスが付きます。</p><ul><li>修復は段階ごとに、決められた品物を期限内に納めます。段階ごとに必要な材料が違います。工程は全4段階です（下の表）。各工程の間にはクールタイム（待ち時間）があります。工程IIからIIIに進むには、メインストーリーの殺人ミステリーを攻略する必要があります。以前の情報にあったタイル・花崗岩・大理石・チュニック・労働者の食料などは、工程Iの画面には出ていませんでした。</li><li>段階ごとの効果は、全島での帝国の土地税の低下と名声の上昇です。ライバルがいると、先に必要量を納めた総督ほど強い効果を得られます。</li><li>工程IVを終了すると、州全体の名声ボーナスと、英雄スペシャリストの出現確率の一時的な上昇が得られます。新しい英雄スペシャリストは3人です。</li><li>儀式を定期的に行うと、効果の持続時間を延ばせます。</li><li>品物は、期限内に、ナウクラティスの近くの「ピラミッドの波止場」に届けます。船の輸送メニューから手動で届けるか、交易路を通じて自動で届けられます。すべての総督が貢献でき、最も多く貢献した人に最高の報酬が出ます。必要な品物の生産量を増やすか、ピラミッドへの輸送ルートに割り当てるナイルの船を増やすと、他の総督に先んじられます（ゲーム内のヘルプで確認）。</li><li>修復したピラミッドは、誰が修復を完了したかに関わらず、アイギュプトのすべての奉唱巫女とギムナシアリコスの公共サービス需要（驚異）を満たします。効果は、ギムナシアリコスが幸福度+4・名声+4、奉唱巫女が幸福度+5・名声+5です（ゲーム内のヘルプと、住民の需要の画面で確認）。</li></ul><h3 id="修復の必要材料" tabindex="-1">修復の必要材料 <a class="header-anchor" href="#修復の必要材料" aria-label="Permalink to &quot;修復の必要材料&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工程</th><th>名前</th><th>必要な材料</th></tr></thead><tbody><tr><td>I</td><td>作業場</td><td>木板300・麻300・オーツ麦300・泥レンガ150・ラクダ150・鉄50</td></tr><tr><td>II</td><td>足場</td><td>木板600・縄600・パン400・石灰岩レンガ200・ラクダ200・オイルランプ100（合計2100t）</td></tr><tr><td>III</td><td>石積み</td><td>花崗岩800・石灰岩レンガ800・チュニック800・鉄400・パン400・書記道具一式100（合計3300t）</td></tr><tr><td>IV</td><td>冠石と外装</td><td>大理石1000・瓦1000・パピルス1000・コンクリート600・アイギュプトの青600・金250（合計4450t）</td></tr><tr><td>儀式</td><td>修復後に繰り返し行う</td><td>納める品物は6種類です。毎回変わるかどうかは未確認です。1回目は、顔料400・オイルランプ400・青スイレン茶400・希少な肉の盛り合わせ200・パン200・象牙の小箱100でした（合計1700t。貢献の目標も1700t）</td></tr></tbody></table><p>儀式で貢献すると、次の3段階の効果が付きます。効果は、ピラミッド修復への貢献度に応じて増減します。どれも属州の島が対象で、持続時間は8時間です。</p><table tabindex="0"><thead><tr><th>段階</th><th>名前</th><th>効果</th></tr></thead><tbody><tr><td>1</td><td>帝国の利益</td><td>ヒロイックの専門家の確率 +4%</td></tr><tr><td>2</td><td>帝国の利益</td><td>名声 +5%、ヒロイックの専門家の確率 +6%</td></tr><tr><td>3</td><td>ピラミッドの修復者</td><td>名声 +10%、ヒロイックの専門家の確率 +10%</td></tr></tbody></table><h2 id="キャラクター" tabindex="-1">キャラクター <a class="header-anchor" href="#キャラクター" aria-label="Permalink to &quot;キャラクター&quot;">​</a></h2><p>メインストーリーは殺人ミステリーで、ナウクラティスで遺体が見つかるところから始まります。ストーリーを飛ばして、島の経営に専念することもできます。ただし、ピラミッドの修復は工程IIからIIIに進むときにストーリーの攻略が必要です。</p><div class="stack-table"><table tabindex="0"><thead><tr><th>名前</th><th>役割</th></tr></thead><tbody><tr><td>ヘロン地方長官（Epistrategos Heron）</td><td>ナウクラティスの皇帝代理人。軍事力はほぼ無く、仲介役・商人</td></tr><tr><td>ウァレリア（Valeria）</td><td>川沿いの小さな港を拠点に、交易帝国を広げる</td></tr><tr><td>カンディス（Kandis）</td><td>ファラオの谷を拠点とする略奪者。身代金を要求し、払わないと攻撃してくる。倒すには、港の破壊と谷への軍の派遣が必要</td></tr><tr><td>デキムス・ナウクラティウス・ネルウァ（Decimus Naukratius Nerva）</td><td>「アイギュプトの暴君」。ライバル総督として追加できる。キャンペーン主人公の父</td></tr></tbody></table></div><p>カンディスの画面の表記は「カシュタのカンディス」です。</p><h2 id="新軍事ユニット・船舶" tabindex="-1">新軍事ユニット・船舶 <a class="header-anchor" href="#新軍事ユニット・船舶" aria-label="Permalink to &quot;新軍事ユニット・船舶&quot;">​</a></h2><ul><li><strong>クマトの弓兵</strong>（Kumatic Archers）：通常の遠距離ユニットより攻撃力・命中率・射程が高い。採用費と維持費も高い。</li><li><strong>ラクダ騎兵部隊</strong>：敵の騎兵・歩兵ユニットの士気を低下させる効果を持ちます。騎馬ユニットに強くやや安価ですが、足の速い馬には追いつけません。</li><li>2体とも、スキルツリーで先に研究する必要があります。スキルツリーの「外人部隊」を解放すると、ラティウム以外でもローマ軍団兵（レギオナリウス）を徴兵できるようになります。</li><li>アイギュプト専用の造船所で、改造できない船を2種建造できます。 <ul><li>エポルキオン（ナイルの小舟）：最初から建造可能。非武装で、貨物スロットは3。航行速度は6〜32ペース（毎秒）、川の速度は64ペース（毎秒）、ヒットポイントは500。</li><li>アバ（ナイルのガレー船）：スキルで解放されます（公式ブログの内容）。民間IIと軍団IIの2タイプがあります。航行速度は5〜29ペース（毎秒）、川の速度は58ペース（毎秒）、ヒットポイントは1,000、建設時間は8分です。 <ul><li>民間II：貨物スロットは5。維持費はコイン35と労働力3。建設費はコイン1,500・葦15・縄10・帆布10。</li><li>軍団II：貨物スロットは4。クマトの弓兵のモジュールが設置済み。維持費はコイン70と労働力6。建設費はコイン1,500・葦15・縄10・帆布10・武器5。</li></ul></li></ul></li><li>ローマ船は外洋向けで頑丈ですが、浅い河口のデルタでは扱いにくく、アイギュプト船は浅瀬に強く速いです。川の輸送は現地の船、地域間の輸送はローマ船に積み替える使い分けが勧められています。海岸近くの貨物ハブも有用とされています。</li></ul><h2 id="その他" tabindex="-1">その他 <a class="header-anchor" href="#その他" aria-label="Permalink to &quot;その他&quot;">​</a></h2><ul><li>他地域との交易により、独自の経済戦略を構築できます。</li></ul><h2 id="無料アップデート3-0の内容" tabindex="-1">無料アップデート3.0の内容 <a class="header-anchor" href="#無料アップデート3-0の内容" aria-label="Permalink to &quot;無料アップデート3.0の内容&quot;">​</a></h2><p>DLC03と同じ<strong>2026年11月5日</strong>（日本時間19:00）に配信されました。スタンプ機能、統計メニューの新しいタブ、難易度の見直し（新しいセーブは「ノーマル」が既定で消費量が増える）、祭りの費用の見直しなどが入っています。</p><p>変更点の一覧は<a href="/guide/patch-notes.html#update-3-0">アップデート・パッチ情報の3.0</a>にまとめています。</p><h2 id="まだ分かっていない要素" tabindex="-1">まだ分かっていない要素 <a class="header-anchor" href="#まだ分かっていない要素" aria-label="Permalink to &quot;まだ分かっていない要素&quot;">​</a></h2><p>以下は、まだ分かっていません。</p><ul><li>ピラミッドの儀式で納める品物が毎回変わるか、品物ごとの貢献度</li><li>数値バランス（生産量・信仰要求量など）の、実機での確認</li></ul><p>数値はゲームのアップデート3.0のゲーム内データが元です。一部の数値は、実機との照合が済んでいません。確かめ次第、直していきます。</p><h2 id="関連データ" tabindex="-1">関連データ <a class="header-anchor" href="#関連データ" aria-label="Permalink to &quot;関連データ&quot;">​</a></h2><ul><li><a href="/wiki/">データベース一覧</a> — 現在公開中のゲームデータ</li></ul>',63)])])}const p=d(i,[["render",e]]);export{c as __pageData,p as default};
